<script setup lang="ts">
import {ref,computed,watch,onMounted} from 'vue';import {useRoute} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {request,upload} from '@/integration/service';
const route=useRoute(),kind=computed(()=>route.path==='/albums'?'albums':'moments'),album=computed(()=>kind.value==='albums'),rows=ref([]),form=ref(null),busy=ref(false),adding=ref(false),filter=ref('all');const visible=computed(()=>filter.value==='all'?rows.value:rows.value.filter(r=>r.status===filter.value));const wallpapers=['fields','dawn','study','room','orbit','journey','fantasy','games'];
async function load(){rows.value=await request('/api/studio/journal/'+kind.value);}function edit(row=null){form.value=row?JSON.parse(JSON.stringify(row)):{title:'',content:'',mood:'晴',status:'draft',images:[]};}
async function addImages(event){adding.value=true;try{for(const file of [...event.target.files]){if(form.value.images.length>=60)break;const r=await upload(file);form.value.images.push({url:r.result.url,caption:''});}}finally{adding.value=false;event.target.value='';}}
async function save(){busy.value=true;try{await request('/api/studio/journal/'+kind.value+(form.value.id?'/'+form.value.id:''),form.value.id?'PUT':'POST',form.value);ElMessage.success('已保存'+(form.value.status==='published'?'并公开':'，仅后台可见'));form.value=null;await load();}catch{/* request already displays the error; preserve the user's form. */}finally{busy.value=false;}}
async function remove(row){try{await ElMessageBox.confirm('删除后将从本站移除。','删除'+row.title,{type:'warning'});}catch{return;}await request('/api/studio/journal/'+kind.value+'/'+row.id,'DELETE',{version:row.version});await load();}
onMounted(async()=>{await load();if(!album.value&&route.query.thought){edit();form.value.content=String(route.query.thought).slice(0,1000);}});watch(kind,()=>{form.value=null;filter.value='all';load();});
</script>
<template><div><div class="journal-admin-heading"><div><span class="studio-eyebrow">{{album?'COLLECT THE LIGHT':'CAPTURE A THOUGHT'}}</span><h1>{{album?'相册管理':'说说管理'}}</h1><p>{{album?'给照片排个顺序，再配上一句当时的心情。':'记录一个想法，不用等它长成一篇文章。'}}</p></div><el-button type="primary" @click="edit()">＋ {{album?'新建相册':'写条说说'}}</el-button></div><el-radio-group v-model="filter" class="journal-state-filter"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="published">公开</el-radio-button><el-radio-button value="draft">草稿</el-radio-button><el-radio-button value="private">私密</el-radio-button></el-radio-group><el-empty v-if="!visible.length" description="从一个小片段开始吧"/><div class="journal-admin-grid"><el-card v-for="row in visible" :key="row.id"><img v-if="row.images[0]" class="journal-admin-cover" :src="row.images[0].url" :alt="row.title"/><div class="journal-admin-meta"><el-tag size="small" :type="row.status==='published'?'success':'info'">{{({published:'公开',draft:'草稿',private:'私密'})[row.status]}}</el-tag><span>{{row.mood}} · {{row.created.slice(0,10)}}</span></div><h2>{{row.title}}</h2><p class="journal-excerpt">{{row.content}}</p><div class="journal-admin-actions"><span>{{row.images.length}} 张照片</span><RouterLink v-if="!album" :to="'/article/addArticle?fromMoment='+row.id" class="expand-moment">扩写成文章</RouterLink><el-button size="small" @click="edit(row)">编辑</el-button><el-button size="small" type="danger" plain @click="remove(row)">删除</el-button></div></el-card></div><el-dialog :model-value="!!form" @update:model-value="v=>{if(!v)form=null}" :title="album?'整理这本相册':'写下此刻'" width="min(760px,94vw)" :close-on-click-modal="false"><el-form v-if="form" label-position="top" @submit.prevent="save"><el-form-item :label="album?'相册名称':'一句小标题（可不填）'"><el-input v-model="form.title" maxlength="100" :required="album" :placeholder="album?'给这本相册起个名字':'朋友圈一样的随笔，直接写正文就好'"/></el-form-item><el-form-item label="正文"><el-input v-model="form.content" type="textarea" :rows="4" maxlength="6000" placeholder="有什么想记下的……"/></el-form-item><div class="journal-form-options"><el-form-item label="心情"><el-select v-model="form.mood"><el-option v-for="m in ['晴','雨','游戏中','追番中','出走','灵感']" :key="m" :value="m"/></el-select></el-form-item><el-form-item label="可见范围"><el-select v-model="form.status"><el-option label="草稿 · 不公开" value="draft"/><el-option label="私密 · 不公开" value="private"/><el-option label="公开展示" value="published"/></el-select></el-form-item></div><el-form-item label="照片"><div class="journal-image-editor"><div v-for="(img,i) in form.images" :key="img.url+i"><img :src="img.url" alt="照片预览"/><el-input v-model="img.caption" placeholder="照片说明" maxlength="200"/><div><el-button size="small" :disabled="i===0" @click="form.images.splice(i-1,0,...form.images.splice(i,1))">前移</el-button><el-button size="small" @click="form.images.splice(i,1)">移除</el-button></div></div></div><label class="image-upload-label">{{adding?'正在上传…':'＋ 上传照片'}}<input type="file" accept="image/png,image/jpeg,image/webp" multiple :disabled="adding" @change="addImages"/></label><p class="upload-note">PNG / JPEG / WebP，每张最多 8MB。相册第一张即封面。</p></el-form-item><el-collapse><el-collapse-item title="或选用已整理的本地风景素材" name="assets"><div class="wallpaper-picker"><button v-for="w in wallpapers" :key="w" type="button" @click="form.images.push({url:'/assets/landscape-'+w+'.webp',caption:''})"><img :src="'/assets/landscape-'+w+'.webp'" :alt="w"/></button></div></el-collapse-item></el-collapse><div class="journal-save"><el-button @click="form=null">取消</el-button><el-button native-type="submit" type="primary" :loading="busy" :disabled="adding">保存{{form.status==='published'?'并公开':''}}</el-button></div></el-form></el-dialog></div></template>
